// モギ glyph atlas: the characters painted on signs, banners and lanterns in the garden, town and sky views.
// Pre-rendered from Noto Serif CJK JP Black (SIL Open Font License 1.1) so signs look the same on every device,
// whatever fonts it has. Only real words are ever drawn; a character missing here draws nothing.
//
//   MogiGlyphs.whenReady            Promise, resolves once the atlas can be drawn (bake after this)
//   MogiGlyphs.ready                true once loaded
//   MogiGlyphs.has(text)            every character of text is in the atlas
//   MogiGlyphs.measure(text, size, vertical) -> {w, h}
//   MogiGlyphs.draw(ctx, text, {x, y, size, vertical, rtl, color, alpha, gap})
//       draws text centred on x,y under ctx's current transform and returns {w, h}.
//       vertical: one character per line, top to bottom.  rtl (horizontal only, default true): Edo order, right to left.
//       size: the character's em in canvas units.  gap: extra space between characters as a fraction of size (default 0.06).
//   MogiGlyphs.drawChar(ctx, ch, x, y, size, color, alpha)   one character centred on x,y
(function (root) {
  var CH = '越後屋伊勢松大黒万丸呉服酒米茶薬蕎麦団子油両替宿そばうどん御休処漬奉納正一位稲荷明神商売繁盛出し名物入芝居千秋楽歌舞伎祭灯献旅籠湯店本堂菓傘紙', CELL = 96, EM = 84, COLS = 10;
  var SRC = 'data:image/png;base64,';
  var idx = {}, i, atlas = null, tints = {}, tintN = 0, done;
  for (i = 0; i < CH.length; i++) idx[CH.charAt(i)] = i;
  var G = { ready: false, chars: CH };
  G.whenReady = new Promise(function (res) { done = res; });
  function finish() { G.ready = !!atlas; done(G); }
  if (typeof document !== 'undefined' && typeof Image !== 'undefined') {
    var img = new Image();
    img.onload = function () {
      try {
        var c = document.createElement('canvas'); c.width = img.width; c.height = img.height;
        var g = c.getContext('2d'); g.drawImage(img, 0, 0);
        var d = g.getImageData(0, 0, c.width, c.height), p = d.data;
        for (var k = 0; k < p.length; k += 4) { p[k + 3] = p[k]; p[k] = p[k + 1] = p[k + 2] = 255; }   // the grey mask becomes white ink with alpha
        g.putImageData(d, 0, 0); atlas = c;
      } catch (e) { atlas = null; }
      finish();
    };
    img.onerror = finish;
    img.src = SRC;
  } else finish();
  function tinted(color) {
    var t = tints[color];
    if (t) return t;
    if (tintN > 24) { tints = {}; tintN = 0; }
    t = document.createElement('canvas'); t.width = atlas.width; t.height = atlas.height;
    var g = t.getContext('2d'); g.drawImage(atlas, 0, 0); g.globalCompositeOperation = 'source-in'; g.fillStyle = color; g.fillRect(0, 0, t.width, t.height);
    tints[color] = t; tintN++;
    return t;
  }
  function chars(text) { return Array.from ? Array.from(String(text)) : String(text).split(''); }
  G.has = function (text) {
    if (!atlas) return false;
    var a = chars(text);
    for (var k = 0; k < a.length; k++) if (a[k] !== ' ' && !(a[k] in idx)) return false;
    return a.length > 0;
  };
  G.measure = function (text, size, vertical, gap) {
    var n = chars(text).length, step = size * (1 + (gap == null ? 0.06 : gap)), len = n ? size + (n - 1) * step : 0;
    return vertical ? { w: size, h: len } : { w: len, h: size };
  };
  G.drawChar = function (ctx, ch, x, y, size, color, alpha) {
    var k = idx[ch];
    if (k == null || !atlas || !(size > 0)) return false;
    var t = tinted(color || '#000'), s = size * CELL / EM, a0 = ctx.globalAlpha;
    if (alpha != null) ctx.globalAlpha = a0 * alpha;
    ctx.drawImage(t, (k % COLS) * CELL, ((k / COLS) | 0) * CELL, CELL, CELL, x - s / 2, y - s / 2, s, s);
    ctx.globalAlpha = a0;
    return true;
  };
  G.draw = function (ctx, text, o) {
    o = o || {};
    var a = chars(text), size = o.size || 16, vert = !!o.vertical, rtl = o.rtl !== false, gap = o.gap == null ? 0.06 : o.gap;
    var m = G.measure(text, size, vert, gap), step = size * (1 + gap), n = a.length, x = o.x || 0, y = o.y || 0;
    for (var k = 0; k < n; k++) {
      var off = (k - (n - 1) / 2) * step;
      if (vert) G.drawChar(ctx, a[k], x, y + off, size, o.color, o.alpha);
      else G.drawChar(ctx, a[k], x + (rtl ? -off : off), y, size, o.color, o.alpha);
    }
    return m;
  };
  root.MogiGlyphs = G;
})(typeof window !== 'undefined' ? window : this);
